def load_custom_fantasy_players() -> List[Player]:
    if not os.path.exists(CUSTOM_PLAYERS_PATH):
        return []
    try:
        with open(CUSTOM_PLAYERS_PATH, "r", encoding="utf-8") as handle:
            payload = json.load(handle)
    except Exception:
        return []
    records = payload.get("players", payload) if isinstance(payload, dict) else payload
    players = []
    for record in records or []:
        player = custom_player_from_record(record)
        if player is not None:
            if not getattr(player, "badges", ()):
                try:
                    assign_player_badges(Team("Custom Player", [player]))
                except NameError:
                    pass
            players.append(player)
    return players


def save_custom_fantasy_players(players: List[Player]):
    payload = {"players": [serialize_custom_player(player) for player in players]}
    with open(CUSTOM_PLAYERS_PATH, "w", encoding="utf-8") as handle:
        json.dump(payload, handle, indent=2)


def infer_custom_player_archetype(player: Player) -> str:
    pos = str(getattr(player, "position", "SF") or "SF").upper()
    three = _rating_to_int(getattr(player, "three_rating", 0.50))
    mid = _rating_to_int(getattr(player, "mid_rating", 0.50))
    rim = _rating_to_int(getattr(player, "rim_rating", 0.50))
    dunk = _rating_to_int(getattr(player, "dunk_rating", 0.50))
    play = _rating_to_int(getattr(player, "playmaking", 0.50))
    handle = _rating_to_int(getattr(player, "ball_handle", 0.50))
    pdef = _rating_to_int(getattr(player, "perimeter_def", 0.50))
    idef = _rating_to_int(getattr(player, "interior_def", 0.50))
    reb = max(_rating_to_int(getattr(player, "oreb", 0.50)), _rating_to_int(getattr(player, "dreb", 0.50)))
    block = _rating_to_int(getattr(player, "block", 0.50))
    iso = _rating_to_int(getattr(player, "iso_tendency", 0.50))

    if pos in ("PG", "SG"):
        if play >= 86 and three >= 84:
            return "shot-making floor general"
        if play >= 88:
            return "floor general"
        if three >= 88 and iso >= 65:
            return "deep-range shot creator"
        if handle >= 86 and rim >= 82:
            return "slashing creator"
        if pdef >= 82:
            return "point-of-attack stopper"
        if three >= 84:
            return "movement shooter"
        return "combo guard"
    if pos == "SF":
        if pdef >= 84 and max(three, rim, mid) >= 82:
            return "two-way wing"
        if play >= 82:
            return "point forward"
        if three >= 86:
            return "scoring wing"
        if dunk >= 84 and rim >= 84:
            return "athletic slasher"
        return "versatile wing"
    if pos == "PF":
        if three >= 84 and idef >= 70:
            return "two-way stretch four"
        if rim >= 86 and idef >= 82:
            return "interior two-way force"
        if three >= 84:
            return "stretch four"
        if reb >= 82 and idef >= 78:
            return "glass-cleaning defender"
        return "frontcourt finisher"
    if idef >= 86 and block >= 82 and rim >= 82:
        return "paint anchor"
    if play >= 82:
        return "post playmaking hub"
    if three >= 82:
        return "stretch five"
    if reb >= 84:
        return "glass-cleaning big"
    return "rim-running center"


