    # play types (drive_kick, iso, post_split, horns, etc.) far more than
    # usage/shot_tendency do -- explicit soft caps keep both featured
    # scorers in real co-star territory instead of Brown getting buried.
    for player in t.roster:
        if player.name == 'Jayson Tatum':
            player.target_fga_soft_cap = 20.0
        elif player.name == 'Jaylen Brown':
            player.target_fga_soft_cap = 19.0
    t.init_lineup()
