def fantasy_team_factories(year_prefix: str = None) -> List:
    factories = []
    seen_team_names = set()

    for name, fn in sorted(globals().items()):
        if not name.startswith("make_") or name in {"make_2016_playoff_team", "make_knicks_2025"}:
            continue
        if not callable(fn):
            continue

        try:
            team = fn()
        except TypeError:
            continue
        except Exception:
            continue

        if not isinstance(team, Team) or team.name in seen_team_names:
            continue
        if year_prefix and not team.name.startswith(year_prefix):
            continue

        seen_team_names.add(team.name)
        factories.append(fn)

    return factories


def gui_team_factories() -> Dict[str, callable]:
    teams = {}
    for factory in fantasy_team_factories():
        try:
            team = factory()
        except Exception:
            continue
        if isinstance(team, Team):
            teams.setdefault(team.name, factory)
    return dict(sorted(teams.items()))

def build_fantasy_player_pools(year_prefix: str = None) -> Dict[str, List[Tuple[Player, str]]]:
    """
    Fantasy draft pool across simulator teams.
    If the same player appears more than once, show him once on the board,
    then let the user choose which simulator version to draft.
    """
    versions_by_name: Dict[str, List[Player]] = {}

    for factory in fantasy_team_factories(year_prefix):
        team = factory()
        if is_olympic_team(team) or team.name in {"1992 USA Dream Team", "2008 USA Redeem Team"}:
            continue
        apply_star_clutchness(team)
        assign_player_badges(team)
        for p in team.roster:
            clone = fantasy_player_clone(p, team.name)
            versions_by_name.setdefault(p.name, []).append(clone)

    for custom_player in load_custom_fantasy_players():
        assign_player_badges(Team("Custom Player", [custom_player]))
        clone = fantasy_player_clone(custom_player, "Custom Player")
        versions_by_name.setdefault(clone.name, []).append(clone)

    pools: Dict[str, List[Tuple[Player, str]]] = {pos: [] for pos in ("PG", "SG", "SF", "PF", "C")}
    for versions in versions_by_name.values():
        versions.sort(key=fantasy_ovr, reverse=True)
        representative = versions[0]
        representative.fantasy_versions = versions
        pos = representative.position if representative.position in pools else "SF"
        ovr = fantasy_ovr(representative)
        version_note = f" | {len(versions)} versions" if len(versions) > 1 else ""
        desc = (
            f"{representative.source_team} - OVR {ovr}{version_note}"
        )
        pools[pos].append((representative, desc))

    for pos in pools:
        pools[pos].sort(key=lambda item: fantasy_ovr(item[0]), reverse=True)

    return pools

